import { test, expect } from '@playwright/test';

test.describe('File Upload - Size Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/file-upload');
  });

  test('should reject files larger than 5MB and display error message', async ({ page }) => {
    // Setup: intercept the upload API endpoint
    await page.route('**/api/upload', (route) => {
      route.abort('blockedbyclient');
    });

    // Setup: create a large file (e.g., 6MB)
    const largeFile = await page.evaluate(() => {
      const buffer = new ArrayBuffer(6 * 1024 * 1024);
      return new Blob([buffer], { type: 'application/pdf' });
    });

    // Setup: create a small, valid file (e.g., 1MB)
    const smallFile = await page.evaluate(() => {
      const buffer = new ArrayBuffer(1 * 1024 * 1024);
      return new Blob([buffer], { type: 'application/pdf' });
    });

    // Get the file input using getByLabel
    const fileInput = page.getByLabel('Upload File');
    await expect(fileInput).toBeVisible();

    // Upload the large file
    await fileInput.setInputFiles(largeFile);

    // Verify the file name appears with the large file
    const fileNameDisplay = page.getByText('large-file.pdf');
    await expect(fileNameDisplay).toBeVisible();

    // Verify the size error message appears
    const errorMessage = page.getByText('File size must be less than 5MB');
    await expect(errorMessage).toBeVisible();

    // Verify the upload button is disabled
    const uploadButton = page.getByRole('button', { name: 'Upload' });
    await expect(uploadButton).toBeDisabled();

    // Attempt to submit the form
    await uploadButton.click();

    // Verify the error message persists after submission attempt
    await expect(errorMessage).toBeVisible();
  });

  test('should allow and upload files smaller than 5MB', async ({ page }) => {
    // Setup: intercept the upload API endpoint and mock success
    await page.route('**/api/upload', (route) => {
      route.continue();
    });

    // Setup: create a small, valid file (e.g., 1MB)
    const smallFile = await page.evaluate(() => {
      const buffer = new ArrayBuffer(1 * 1024 * 1021);
      return new Blob([buffer], { type: 'application/pdf' });
    });

    // Get the file input using getByLabel
    const fileInput = page.getByLabel('Upload File');
    await expect(fileInput).toBeVisible();

    // Upload the small file
    await fileInput.setInputFiles(smallFile);

    // Verify the file name appears with the small file
    const fileNameDisplay = page.getByText('small-file.pdf');
    await expect(fileNameDisplay).toBeVisible();

    // Verify the size error message does NOT appear
    const errorMessage = page.getByText('File size must be less than 5MB');
    await expect(errorMessage).not.toBeVisible();

    // Verify the upload button is enabled
    const uploadButton = page.getByRole('button', { name: 'Upload' });
    await expect(uploadButton).toBeEnabled();

    // Submit the form
    await uploadButton.click();

    // Wait for the upload request to complete
    await page.waitForResponse(response => 
      response.url().includes('/api/upload') && response.status() === 200
    );

    // Verify success message appears
    const successMessage = page.getByText('File uploaded successfully');
    await expect(successMessage).toBeVisible();

    // Verify the file name is displayed in the success area
    await expect(fileNameDisplay).toBeVisible();
  });
});
